            m_b_resp_buf <= 1'b0;
        end else if (m_b_valid_and_ready) begin
            m_b_resp_valid <= 1'b1;
            m_b_resp_buf <= m_axil_bresp;
        end else begin
            m_b_resp_valid <= 1'b0;
        end
    end

